-- Difficulty selector and endings. Existing UI keys and player data are preserved.

UPDATE game_locale_ui SET ui = json_set(ui, '$.btn_shop', 'Чёрный рынок', '$.difficulty', json('{"label": "Сложность", "close": "Закрыть", "restart": "Смена сложности начнёт новый срок с нуля. Текущая партия будет сброшена. Продолжить?", "easy": {"name": "Простой"}, "normal": {"name": "Нормальный"}, "hard": {"name": "Сложный"}, "insane": {"name": "Сумасшедший"}}'), '$.titles.bankruptcy', 'Мэр без бюджета', '$.titles.too_popular', 'Слишком народный мэр', '$.titles.wife_abroad', 'Мэр на чемоданах'),
    alerts = json_set(alerts, '$.bankruptcy', 'Деньги закончились, полномочия тоже. За банкротство вас сняли с должности.', '$.too_popular', 'Рейтинг достиг 100%. Однопартийцы решили, что такой популярный конкурент им не нужен, и убрали вас с поста.', '$.wife_abroad', 'Жена довольна на все 100% и решила, что пора жить для себя. Чемоданы собраны — пост придётся оставить.') WHERE lang = 'ru';

UPDATE game_locale_ui SET ui = json_set(ui, '$.btn_shop', 'Black Market', '$.difficulty', json('{"label": "Difficulty", "close": "Close", "restart": "Changing difficulty starts a new term from scratch. Your current game will be reset. Continue?", "easy": {"name": "Easy"}, "normal": {"name": "Normal"}, "hard": {"name": "Hard"}, "insane": {"name": "Insane"}}'), '$.titles.bankruptcy', 'Mayor Without a Budget', '$.titles.too_popular', 'Too Popular for Office', '$.titles.wife_abroad', 'Mayor on the Move'),
    alerts = json_set(alerts, '$.bankruptcy', 'Your funds ran out. So did your mandate. You have been removed from office for bankruptcy.', '$.too_popular', 'Your approval reached 100%. Your party decided it could do without such a popular rival and removed you from office.', '$.wife_abroad', 'Your wife is 100% happy and ready for a new life abroad. The bags are packed. Your term is over.') WHERE lang = 'en';

UPDATE game_locale_ui SET ui = json_set(ui, '$.btn_shop', 'השוק השחור', '$.difficulty', json('{"label": "רמת קושי", "close": "סגירה", "restart": "שינוי רמת הקושי יתחיל כהונה חדשה מאפס. המשחק הנוכחי יתאפס. להמשיך?", "easy": {"name": "קל"}, "normal": {"name": "רגיל"}, "hard": {"name": "קשה"}, "insane": {"name": "מטורף"}}'), '$.titles.bankruptcy', 'ראש עיר בלי תקציב', '$.titles.too_popular', 'פופולרי מדי לתפקיד', '$.titles.wife_abroad', 'ראש עיר על מזוודות'),
    alerts = json_set(alerts, '$.bankruptcy', 'נגמר הכסף, נגמרה הכהונה. הודחת בגלל פשיטת רגל.', '$.too_popular', 'התמיכה הגיעה ל־100%. חברי המפלגה החליטו שמתחרה פופולרי כל כך מיותר להם, והדיחו אותך.', '$.wife_abroad', 'אשתך מרוצה במאה אחוז והחליטה שהגיע הזמן לחיים חדשים בחו״ל. המזוודות מוכנות — התפקיד נשאר בארץ.') WHERE lang = 'he';

UPDATE game_locale_ui SET ui = json_set(ui, '$.btn_shop', 'Чорний ринок', '$.difficulty', json('{"label": "Складність", "close": "Закрити", "restart": "Зміна складності почне новий строк із нуля. Поточну гру буде скинуто. Продовжити?", "easy": {"name": "Простий"}, "normal": {"name": "Нормальний"}, "hard": {"name": "Складний"}, "insane": {"name": "Божевільний"}}'), '$.titles.bankruptcy', 'Мер без бюджету', '$.titles.too_popular', 'Занадто народний мер', '$.titles.wife_abroad', 'Мер на валізах'),
    alerts = json_set(alerts, '$.bankruptcy', 'Гроші скінчилися, повноваження теж. За банкрутство вас усунули з посади.', '$.too_popular', 'Рейтинг досяг 100%. Однопартійці вирішили, що такий популярний конкурент їм не потрібен, і усунули вас із посади.', '$.wife_abroad', 'Дружина задоволена на всі 100% і вирішила почати нове життя за кордоном. Валізи зібрано — посаду доведеться залишити.') WHERE lang = 'uk';
